import {mergeDiaryStates,digestText} from './merge-core.mjs';
let mergeJob=null;
const mergeInput=document.createElement('input');mergeInput.type='file';mergeInput.accept='.json,application/json';mergeInput.hidden=true;document.body.append(mergeInput);
const backupBeforeMerge=openBackup;
openBackup=function(){backupBeforeMerge();const button=document.createElement('button');button.className='upload-zone';button.id='merge-backup';button.style.marginTop='15px';button.innerHTML='<span>⇄</span>合并导入手机日记<small class="hint">保留当前内容 · 补入新素材 · 冲突保留两个版本</small>';$('#restore-backup').before(button);button.onclick=()=>mergeInput.click();$('#restore-backup').querySelector('small').textContent='替换当前日记；合并手机内容请用上面的“合并导入”';};
function stopMerge(){if(mergeJob)mergeJob.cancelled=true;mergeJob=null;}
$('#editor').addEventListener('close',stopMerge);
function progress(job,text){if(job.cancelled||mergeJob!==job)throw Error('已取消合并');const el=$('#merge-progress');if(el)el.textContent=text;}
async function blobHash(blob){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('');}
function fileBatch(files,remove=false){if(!files.length)return Promise.resolve();if(!db)throw Error('当前浏览器无法保存素材。');return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite'),store=tx.objectStore('files');for(const file of files)if(remove)store.delete(file.id);else store.put(file.blob,file.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('素材保存失败'));tx.onabort=()=>reject(tx.error||Error('素材保存中断'));});}
mergeInput.onchange=async()=>{const file=mergeInput.files[0];mergeInput.value='';if(!file)return;stopMerge();const job={cancelled:false};mergeJob=job;showDialog('合并手机日记',`<p>正在检查文件与重复素材，尚未修改当前日记。</p><p id="merge-progress" aria-live="polite">正在读取…</p><div class="form-actions"><button id="merge-cancel" class="outline-btn">取消</button></div>`);$('#merge-cancel').onclick=()=>{stopMerge();openBackup();};try{
 const baseline=localStorage.getItem('along-the-way-v1'),data=JSON.parse(await file.text());if(data.format!=='along-the-way-backup'||data.version!==1||!Array.isArray(data.files))throw Error('请选择“导出完整日记”生成的 JSON，不能使用行程路线 JSON。');const incoming=validateState(data.state),refs=referencedIds(incoming),rawFiles=new Map();for(const f of data.files){if(typeof f.id!=='string'||rawFiles.has(f.id))throw Error('备份的素材编号重复或无效。');rawFiles.set(f.id,f.data);}for(const id of refs)if(typeof rawFiles.get(id)!=='string'||!/^data:(image|video|audio)\/[\w.+-]+;base64,/.test(rawFiles.get(id)))throw Error('备份缺少素材，或包含不支持的文件。');
 const localIds=new Set(referencedIds(state)),localBlobs=new Map(),byHash=new Map(),hashes={};for(const [i,id]of [...localIds].entries()){progress(job,`检查当前素材 ${i+1} / ${localIds.size}`);const blob=await getFile(id);localBlobs.set(id,blob);if(blob){const hash=await blobHash(blob);hashes[id]=hash;if(!byHash.has(hash))byHash.set(hash,id);}}
 const mediaMap=new Map(),writes=[],sourceHashes=[];let duplicates=0;for(const [i,id]of refs.entries()){progress(job,`检查手机素材 ${i+1} / ${refs.length}`);const blob=await fetch(rawFiles.get(id)).then(r=>r.blob()),hash=await blobHash(blob);sourceHashes.push([id,hash]);let target;if(hashes[id]===hash)target=id;else target=byHash.get(hash);if(target)duplicates++;else{target=localIds.has(id)&&!localBlobs.get(id)?id:uid();writes.push({id:target,blob,repair:localIds.has(target)});byHash.set(hash,target);hashes[target]=hash;}mediaMap.set(id,target);}
 const receipt=await digestText(JSON.stringify({state:data.state,files:sourceHashes}));progress(job,'正在比较路线、文字与排版…');const result=await mergeDiaryStates(state,incoming,mediaMap,{newId:uid,hashes});for(const t of result.state.trips)for(const s of t.stops)if(s.design)ensureStopDesign(t,s);result.state.settings.mergeReceipts={...result.state.settings.mergeReceipts,[receipt]:true};const st=result.stats;
 progress(job,'检查完成');showDialog('确认合并手机日记',`<p>当前日记会保留。手机内容将按旅行、日期和站点匹配后补入。</p><ul class="merge-counts"><li>新增旅行：${st.trips} 段</li><li>新增站点 / 版本：${st.stops} 个</li><li>补入影像：${st.media} 个</li><li>新增素材文件：${writes.length} 个；重复素材：${duplicates} 个</li><li>文字、排版或定位冲突：${st.versions} 个导入版本</li></ul><p class="hint">原定位、文字和排版不被覆盖。导入版本会单独标记；重复导入不会重复添加，可撤销本次合并。</p><div id="merge-progress" class="hint" aria-live="polite"></div><div class="form-actions"><button id="merge-cancel" class="text-btn">取消</button><button id="merge-confirm" class="primary-btn">合并到当前日记</button></div>`);$('#merge-cancel').onclick=()=>{stopMerge();openBackup();};$('#merge-confirm').onclick=async()=>{const button=$('#merge-confirm');button.disabled=true;$('#merge-cancel').disabled=true;let written=false,committed=false;try{if(localStorage.getItem('along-the-way-v1')!==baseline)throw Error('其他标签页已修改日记。请刷新后重新合并，以保留最新内容。');const serialized=JSON.stringify(result.state);progress(job,'正在保存素材，请保持此页面打开…');await fileBatch(writes);written=true;if(job.cancelled)throw Error('已取消合并');if(localStorage.getItem('along-the-way-v1')!==baseline)throw Error('其他标签页已修改日记，请刷新后重新合并。');localStorage.setItem('along-the-way-v1',serialized);committed=true;snapshot();state=result.state;render();closeDialog();toast('手机日记已合并，原有内容保留。可在“我的路线”撤销上次修改。');}catch(e){if(written&&!committed)await fileBatch(writes.filter(f=>!f.repair),true).catch(()=>{});notifyError(e);if(button.isConnected){button.disabled=false;$('#merge-cancel').disabled=false;}}};
 }catch(e){if(!job.cancelled){openBackup();notifyError(e);}}};
